ee:message.ee:set-payload:
%dw 2.0
output application/json
import mergeWith from dw::core::Objects
var poles = payload[0].Orden_Activacion.Postes_Instalacion
var formatedDate = now() >> "America/Bogota"
---
{
	"updateType": "Poles",
	"toUpdate": poles map ((item, index) -> 
		item mergeWith {
			Estado: vars.newPoleState,
			Fecha_Modificacion: formatedDate,
			(Tipo_Intervencion: p('posteria.Tipo_Intervencion')) if (vars.operacion == "DESMONTE")
		}
	)
}
